CREATE TABLE IF NOT EXISTS tournaments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, game TEXT NOT NULL, format TEXT NOT NULL DEFAULT 'Solo', mode TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'DRAFT', prize_pool TEXT NOT NULL DEFAULT '0', registration_fee TEXT NOT NULL DEFAULT '0', date TEXT NOT NULL DEFAULT '', schedule TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', registration_url TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());